// These illustrations are authored as layered SVG so every lid and paper sheet can respond to input.
const hash=text=>{let n=0;for(const c of text)n=(n*31+c.charCodeAt(0))>>>0;return n;};
export function activitySession(type,key,seed='ENT'){
  if(type==='printer')return{view:'front',open:null,jamAt:hash(seed+'|'+key)%2?'rear':'tray',removed:false};
  if(type==='tissue')return{cabinet:false,holding:false,lid:false,loaded:false};
  return{digits:'',connected:false};
}
export function printerAction(s,action){
  if(['front','back'].includes(action)){s.view=action;return'view';}
  if(['tray','rear','out'].includes(action)){if((action==='rear')!==(s.view==='back'))return'blocked';s.open=s.open===action?null:action;return s.open===s.jamAt&&!s.removed?'found':'inspect';}
  if(action==='remove'){if(s.removed||s.open!==s.jamAt||(s.jamAt==='rear')!==(s.view==='back'))return'blocked';s.removed=true;return'removed';}
  if(action==='test')return s.removed&&s.open===null?'done':'blocked';
  return'blocked';
}
export function tissueAction(s,action){
  if(action==='cabinet'){s.cabinet=!s.cabinet;return'cabinet';}
  if(action==='take'&&s.cabinet&&!s.holding&&!s.loaded){s.holding=true;return'taken';}
  if(action==='box'&&!s.loaded){if(!s.lid){s.lid=true;return'lid';}if(s.holding){s.holding=false;s.loaded=true;s.lid=false;return'loaded';}s.lid=false;return'empty';}
  if(action==='test'&&s.loaded)return'done';
  return'blocked';
}
export function maintenanceAction(s,action){
  if(/^\d$/.test(action)&&!s.connected){s.digits=(s.digits+action).slice(0,4);return'digit';}
  if(action==='clear'){s.digits='';s.connected=false;return'clear';}
  if(action==='erase'&&!s.connected){s.digits=s.digits.slice(0,-1);return'erase';}
  if(action==='call'){if(s.digits==='3000'){s.connected=true;return'connected';}return s.digits.length===4?'wrong':'short';}
  return action==='report'&&s.connected?'done':'blocked';
}
