const hit=(action,label,left,top,width,height,extra='')=>`<button class="model-hit ${extra}" data-object-action="${action}" aria-label="${label}" style="left:${left}%;top:${top}%;width:${width}%;height:${height}%"><span>${label}</span></button>`;
