  const rear=`<path d="M146 151 386 151 386 336 146 336Z" fill="url(#deviceFace)"/><path d="M386 151 465 113 465 298 386 336Z" fill="url(#deviceSide)"/><path d="M146 151 224 110 465 113 386 151Z" fill="url(#deviceTop)"/><rect x="164" y="179" width="205" height="126" rx="5" fill="#c4cece" stroke="#8b9fa6" stroke-width="2"/><rect x="224" y="188" width="88" height="12" rx="5" fill="#748b93"/><path d="M180 218h172m-172 9h172m-172 9h172m-172 9h172m-172 9h172" stroke="#879c9e" stroke-width="3"/><rect x="399" y="227" width="29" height="20" fill="#263f4c"/><path d="M413 241q37 67 86 73" fill="none" stroke="#304653" stroke-width="5"/><circle cx="179" cy="286" r="4" fill="#7b9098"/><circle cx="354" cy="286" r="4" fill="#7b9098"/>`;
  const tray=open==='tray'&&!back?`<g class="open-paper-tray"><path d="M155 245 376 245 376 316 155 316Z" fill="#405965"/><path d="M156 298 376 298 397 366 130 366Z" fill="#aebec1" stroke="#758e98"/><path d="M173 307 354 307 367 344 157 344Z" fill="#f3f2e8"/><path d="M170 314h187m-190 8h193m-195 8h197" stroke="#d2d6d0"/><path d="M130 366 397 366 397 385 130 385Z" fill="url(#deviceFace)" stroke="#91a2a6"/><rect x="228" y="371" width="68" height="7" rx="3" fill="#7c929a"/>${jam?sheet(220,301,102,51):''}</g>`:'';
  const rearOpen=open==='rear'&&back?`<g class="open-rear-panel"><rect x="164" y="179" width="205" height="126" rx="5" fill="#263e49"/><path d="M175 210h180m-180 61h180" stroke="#98a8a5" stroke-width="7"/>${rollers}<path d="M165 303 368 303 393 367 139 367Z" fill="#849b9f" stroke="#5b7780"/><path d="M180 316 355 316 369 352 163 352Z" fill="#536e77"/><path d="M175 326h182m-186 8h192m-196 8h198" stroke="#789095"/>${jam?sheet(211,218,112,78):''}</g>`:'';
